										class="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-ui-action text-sm font-bold text-ui-onPrimary"
									>
										{{ initials(a.label) }}
									</span>
									<span class="min-w-0 flex-1">
										<span
											class="block truncate text-base font-bold text-ui-heading"
											>{{ a.label }}</span
										>
										<span class="block truncate text-sm text-ui-subtle">{{
											a.value
										}}</span>
									</span>
								</button>
								<p
									v-if="!filteredAssignees.length"
									class="py-8 text-center text-base text-ui-ink-gray-400"
								>
									Tidak ada hasil
								</p>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ===== Bottom sheet: Reference Type ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showRefType"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="showRefType = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showRefType"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.5rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
							<h2 class="mb-2 text-center text-xl font-bold text-ui-heading">
								Reference Type
							</h2>
							<button
								v-for="t in referenceTypes"
								:key="t"
								type="button"
								@click="pickRefType(t)"
								class="flex w-full items-center gap-4 border-b border-ui-line-gray-100 py-4 text-left last:border-b-0"
							>
								<span
									class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2"
									:class="
										form.reference_type === t
											? 'border-ui-action'
											: 'border-ui-line-gray-300'
									"
								>
									<span
										v-if="form.reference_type === t"
										class="h-3 w-3 rounded-full bg-ui-action"
									/>
								</span>
								<span class="text-lg font-bold text-ui-heading">{{ t }}</span>
							</button>
							<p
								v-if="!referenceTypes.length"
								class="py-6 text-center text-base text-ui-ink-gray-400"
							>
								Tidak ada pilihan
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ===== Bottom sheet: Reference Name ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showRefName"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="showRefName = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showRefName"
							class="flex max-h-[85vh] w-full max-w-screen-sm flex-col rounded-t-3xl bg-ui-surface px-5 pb-[max(1.5rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
							<h2 class="mb-4 text-center text-xl font-bold text-ui-heading">
								Reference Name
							</h2>

							<div
								class="mb-3 flex items-center gap-3 rounded-full border border-ui-line-gray-200 bg-ui-surface px-5 py-3.5 focus-within:border-ui-action"
							>
								<svg
									class="h-6 w-6 shrink-0 text-ui-subtle"
									viewBox="0 0 24 24"
									fill="none"
									stroke="currentColor"
									stroke-width="1.8"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<circle cx="11" cy="11" r="7.5" />
									<path d="m20 20-3.6-3.6" />
								</svg>
								<input
									v-model="refNameSearch"
									type="text"
									placeholder="Search"
									class="w-full border-0 bg-transparent p-0 text-lg text-ui-heading placeholder-ui-ink-gray-400 focus:outline-none focus:ring-0"
								/>
							</div>

							<div class="-mx-1 flex-1 overflow-y-auto px-1">
								<button
									v-for="n in filteredRefNames"
									:key="n.value"
									type="button"
									@click="pickRefName(n)"
									class="flex w-full items-center gap-4 border-b border-ui-line-gray-100 py-4 text-left last:border-b-0"
								>
									<span
										class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2"
										:class="
											form.reference_name === n.value
												? 'border-ui-action'
												: 'border-ui-line-gray-300'
										"
									>
										<span
											v-if="form.reference_name === n.value"
											class="h-3 w-3 rounded-full bg-ui-action"
										/>
									</span>
									<span
										class="min-w-0 flex-1 truncate text-base font-medium text-ui-heading"
										>{{ n.label }}</span
									>
								</button>
								<p
									v-if="!filteredRefNames.length"
									class="py-8 text-center text-base text-ui-ink-gray-400"
								>
									Tidak ada hasil
								</p>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource, toast } from 'frappe-ui'

const props = defineProps({ name: { type: String, default: '' } })
const isEdit = computed(() => !!props.name)

const router = useRouter()
function goBack() {
	if (isEdit.value) router.push({ name: 'ToDoDetail', params: { name: props.name } })
	else router.push({ name: 'ToDoList' })
}

const PRIORITY_OPTIONS = ['High', 'Medium', 'Low']

function pad(n) {
	return String(n).padStart(2, '0')
}
function fmtYmd(d) {
	return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	if (!y || !m || !d) return new Date()
	return new Date(y, m - 1, d)
}

const form = reactive({
	date: '',
	priority: '',
	allocated_to: '',
	description: '',
	reference_type: '',
	reference_name: '',
})

// ===== Opsi dropdown =====
const assigneesRes = createResource({
	url: 'juragan.api.portal.todo.get_assignees',
	method: 'GET',
	auto: true,
})
const assignees = computed(() => assigneesRes.data || [])

const refTypesRes = createResource({
	url: 'juragan.api.portal.todo.get_reference_types',
	method: 'GET',
	auto: true,
})
const referenceTypes = computed(() => refTypesRes.data || [])

const refNamesRes = createResource({
	url: 'juragan.api.portal.todo.get_reference_names',
	method: 'GET',
	auto: false,
	makeParams: () => ({ reference_type: form.reference_type }),
})
const referenceNames = computed(() => refNamesRes.data || [])

// ===== Mode edit: muat data ToDo lalu prefill form =====
if (isEdit.value) {
	createResource({
		url: 'juragan.api.portal.todo.get_todo',
		method: 'GET',
		auto: true,
		makeParams: () => ({ name: props.name }),
		onSuccess: (d) => {
			form.date = d.date || ''
			form.priority = d.priority || ''
			form.allocated_to = d.allocated_to || ''
			form.description = plainText(d.description)
			form.reference_type = d.reference_type || ''
			form.reference_name = d.reference_name || ''
			// Muat opsi reference name agar label-nya tampil.
			if (form.reference_type) refNamesRes.reload()
		},
	})
}

function plainText(html) {
	if (!html) return ''
	return String(html)
		.replace(/<\/(p|div|br)>/gi, '\n')
		.replace(/<br\s*\/?>(?!$)/gi, '\n')
		.replace(/<[^>]*>/g, '')
		.replace(/&nbsp;/g, ' ')
		.replace(/\n{3,}/g, '\n\n')
		.trim()
}

// ===== Label tampilan field =====
const assignLabel = computed(() => {
	const cur = assignees.value.find((a) => a.value === form.allocated_to)
	return cur ? cur.label : ''
})
const refNameLabel = computed(() => {
	const cur = referenceNames.value.find((n) => n.value === form.reference_name)
	return cur ? cur.label : ''
})

function initials(name) {
	const parts = String(name || '')
		.trim()
		.split(/\s+/)
		.filter(Boolean)
	if (!parts.length) return '?'
	if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
	return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}

// ===== Modal kalender =====
const WEEKDAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S']
const MONTHS = [
	'January',
	'February',
	'March',
	'April',
	'May',
	'June',
	'July',
	'August',
	'September',
	'October',
	'November',
	'December',
]
const DAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

const showCalendar = ref(false)
const calView = ref(new Date()) // bulan yang sedang ditampilkan
const calSelected = ref(new Date()) // tanggal terpilih sementara

// Mode input manual (ketik Tanggal/Bulan/Tahun)
const calManualMode = ref(false)
const mDay = ref('')
const mMonth = ref('')
const mYear = ref('')

function openCalendar() {
	const base = form.date ? parseYmd(form.date) : new Date()
	calSelected.value = base
	calView.value = new Date(base.getFullYear(), base.getMonth(), 1)
	calManualMode.value = false
	showCalendar.value = true
}

function seedManual() {
	mDay.value = String(calSelected.value.getDate())
	mMonth.value = String(calSelected.value.getMonth() + 1)
	mYear.value = String(calSelected.value.getFullYear())
}
function applyManual() {
	const y = parseInt(mYear.value, 10)
	let mo = parseInt(mMonth.value, 10)
	let d = parseInt(mDay.value, 10)
	if (!y || y < 1900 || y > 2200) return // tunggu tahun valid
	if (!mo || mo < 1) mo = 1
	if (mo > 12) mo = 12
	const maxDay = new Date(y, mo, 0).getDate()
	if (!d || d < 1) d = 1
	if (d > maxDay) d = maxDay
	calSelected.value = new Date(y, mo - 1, d)
	calView.value = new Date(y, mo - 1, 1)
}
function toggleManual() {
	if (!calManualMode.value) {
		seedManual()
	} else {
		applyManual() // sinkronkan nilai ketikan ke kalender
	}
	calManualMode.value = !calManualMode.value
}

const calGrid = computed(() => {
	const y = calView.value.getFullYear()
	const m = calView.value.getMonth()
	const firstDow = new Date(y, m, 1).getDay()
	const daysInMonth = new Date(y, m + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < firstDow; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(d)
	return cells
})
const calMonthLabel = computed(
	() => `${MONTHS[calView.value.getMonth()]} ${calView.value.getFullYear()}`
)
const calHeaderLabel = computed(() => {
	const d = calSelected.value
	return `${DAYS_SHORT[d.getDay()]}, ${MONTHS[d.getMonth()].slice(0, 3)} ${d.getDate()}`
})

function prevMonth() {
	const d = calView.value
	calView.value = new Date(d.getFullYear(), d.getMonth() - 1, 1)
}
function nextMonth() {
	const d = calView.value
	calView.value = new Date(d.getFullYear(), d.getMonth() + 1, 1)
}
function pickDay(d) {
	calSelected.value = new Date(calView.value.getFullYear(), calView.value.getMonth(), d)
}
function isSelDay(d) {
	const s = calSelected.value
	return (
		s.getDate() === d &&
		s.getMonth() === calView.value.getMonth() &&
		s.getFullYear() === calView.value.getFullYear()
	)
}
function confirmCalendar() {
	if (calManualMode.value) applyManual()
	form.date = fmtYmd(calSelected.value)
	showCalendar.value = false
}

// ===== Bottom sheet: Priority =====
const showPriority = ref(false)
function pickPriority(p) {
	form.priority = p
	showPriority.value = false
}

// ===== Bottom sheet: Assign To =====
const showAssign = ref(false)
const assignSearch = ref('')
function openAssign() {
	assignSearch.value = ''
	showAssign.value = true
}
const filteredAssignees = computed(() => {
	const q = assignSearch.value.trim().toLowerCase()
	if (!q) return assignees.value
	return assignees.value.filter(
		(a) =>
			String(a.label).toLowerCase().includes(q) || String(a.value).toLowerCase().includes(q)
	)
})
function pickAssignee(a) {
	form.allocated_to = a.value
	showAssign.value = false
}

// ===== Bottom sheet: Reference Type =====
const showRefType = ref(false)
function pickRefType(t) {
	if (form.reference_type !== t) {
		form.reference_type = t
		form.reference_name = ''
		refNamesRes.reload()
	}
	showRefType.value = false
}

// ===== Bottom sheet: Reference Name =====
const showRefName = ref(false)
const refNameSearch = ref('')
const filteredRefNames = computed(() => {
	const q = refNameSearch.value.trim().toLowerCase()
	if (!q) return referenceNames.value
	return referenceNames.value.filter((n) => String(n.label).toLowerCase().includes(q))
})
function pickRefName(n) {
	form.reference_name = n.value
	showRefName.value = false
}

// ===== Simpan =====
const saving = ref(false)
const createRes = createResource({
	url: 'juragan.api.portal.todo.create_todo',
	method: 'POST',
})
const updateRes = createResource({
	url: 'juragan.api.portal.todo.update_todo',
	method: 'POST',
})

async function submit() {
	if (!form.date) {
		toast.error('Date wajib diisi.')
		return
	}
	if (!form.description.trim()) {
		toast.error('Description wajib diisi.')
		return
	}
	saving.value = true
	const payload = {
		date: form.date,
		description: form.description,
		priority: form.priority || undefined,
		allocated_to: form.allocated_to || undefined,
		reference_type: form.reference_type || undefined,
		reference_name: form.reference_name || undefined,
	}
	try {
		if (isEdit.value) {
			await updateRes.submit({ name: props.name, ...payload })
			toast.success('ToDo berhasil diperbarui.')
			router.push({ name: 'ToDoDetail', params: { name: props.name } })
		} else {
			await createRes.submit(payload)
			toast.success('ToDo berhasil dibuat.')
			router.push({ name: 'ToDoList' })
		}
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal menyimpan ToDo.')
	} finally {
		saving.value = false
	}
}
</script>
